self.addEventListener('message',e=>{const d=e.data||{};
  if(d.hsOff==='stand')e.waitUntil(stand().then(s=>melden({art:'stand',stand:s})));
  if(d.hsOff==='laden')e.waitUntil(laden(true));
  if(d.hsOff==='loeschen')e.waitUntil((async()=>{await caches.delete(DATEN);await caches.delete(MARK);await melden({art:'stand',stand:await stand()})})())});
